import {drugReference} from './medication-data.js';
export const ZENIX_MAX_ENERGY=200;
export const zenixManual='https://www.zoll.com/-/media/product-materials/product-manuals/zenix/01/9650-000421-01-sf_b.ashx?sc_lang=en-us';
export const shockDevices=[{id:'zenix',name:'ZOLL Zenix',short:'Zenix',max:200,manual:zenixManual,manualPage:91},{id:'lifepak15',name:'LIFEPAK 15',short:'LIFEPAK 15',max:360,manual:'https://www.stryker.com/content/dam/stryker/ems/resources/operating-instructions/international/3314911-030_int-eng_lifepak_15_operating_instructions.pdf',manualPage:139}];
export const selectedShockDevice=fields=>shockDevices.find(d=>d.id===fields['shock-device'])||shockDevices[0];
export const shockDevicePicker=fields=>`<div class="shock-device-choices" role="group" aria-label="Select defibrillator">${shockDevices.map(d=>`<button data-shock-device="${d.id}" aria-pressed="${selectedShockDevice(fields).id===d.id}"><b>${d.name}</b><span>${d.max} J max · biphasic</span></button>`).join('')}</div>`;
export const shockProtocols=[
 {id:'C300',label:'VF / pulseless VT',context:'Adult · no pulse',page:75,mode:'UNSYNCHRONIZED',initial:'200',steps:['200','200'],stepLabels:['Next shock','Further shocks'],note:'C300 calls for maximum energy: 200 J on your Zenix for each indicated shock. Resume CPR immediately after each shock; reassess at the next 2-minute rhythm check.'},
 {id:'C303',label:'Wide complex · unstable',context:'Adult · with pulse',page:79,mode:'SYNCHRONIZED',initial:'100',steps:['200'],ceiling:true,note:'C303 starting dose: 100 J, then 200 J if unsuccessful. If the rhythm recurs, use the previously successful energy.',syncNote:'Synchronize unless it is impossible (for example, an irregular rhythm), per C303.',sedation:'versed-cardioversion'},
 {id:'C306',label:'Narrow complex · unstable',context:'Adult · with pulse',page:82,mode:'SYNCHRONIZED',sedation:'versed-cardioversion-narrow'}
];
export function selectedShockProtocol(fields){return shockProtocols.find(p=>p.id===fields['shock-protocol'])||null;}
export function shockPlan(fields){
 const protocol=selectedShockProtocol(fields);if(!protocol)return null;
 const device=selectedShockDevice(fields),max=String(device.max);
 if(protocol.id==='C300')return {...protocol,initial:max,steps:[max,max],device,note:`C300 calls for maximum energy: ${max} J on your ${device.short} for each indicated shock. Resume CPR immediately after each shock; reassess at the next 2-minute rhythm check.`};
 if(protocol.id==='C303')return {...protocol,device,steps:device.id==='lifepak15'?['200','300','360']:['200'],note:`C303: increase energy after unsuccessful shocks, up to ${max} J on your ${device.short}. If the rhythm recurs, use the previously successful energy.`};
 const storedRhythm=fields['shock-narrow-rhythm'];
 const rhythm=storedRhythm==='irregular-monophasic'?'irregular-biphasic':['regular','irregular-biphasic'].includes(storedRhythm)?storedRhythm:'regular';
 const higher=device.id==='lifepak15'?['200','300','360']:['200'];
 const plans={regular:{initial:'50–100',steps:['100',...higher]},'irregular-biphasic':{initial:device.id==='lifepak15'?'125–200':'120–200',steps:higher}};
 return {...protocol,...plans[rhythm],device,rhythm,ceiling:true,note:'After an unsuccessful shock, use the next higher energy than the previous shock. Skip settings already reached; never step down.'+(device.id==='lifepak15'&&rhythm==='irregular-biphasic'?' C306 starts at 120–200 J biphasic; 125 J is the lowest LIFEPAK 15 setting in that range.':'')};
}
export function adultShockSedation(fields){const selected=selectedShockProtocol(fields);return selected?.sedation?drugReference.find(m=>m.id==='midazolam').pathways.find(p=>p.id===selected.sedation):null;}
const step=(dose,label)=>`<div class="shock-energy-step"><span>${label}</span><strong>${dose}<small>J</small></strong></div>`;
function sedationGuide(fields,source,icon){const path=adultShockSedation(fields);if(!path)return `<button class="shock-sedation-link" data-page="sedation">${icon('syringe')}<span><b>Open sedation guide</b><small>Indication-specific doses</small></span>${icon('arrow')}</button>`;
 const recipe=path.recipes[0];return `<aside class="shock-sedation" aria-labelledby="shock-sedation-title"><div class="shock-sedation-heading"><h3 id="shock-sedation-title">Adult sedation · ${path.code}</h3>${source(path.code+' · SEDATION',path.page)}</div><div class="shock-sedation-dose"><div><b>Midazolam / Versed</b><strong>${recipe.low}–${recipe.high} <small>${recipe.unit}</small></strong></div><div class="shock-sedation-routes">${recipe.route.split(' / ').map(route=>`<span>${route}</span>`).join('')}</div></div><p><b>Maximum ${recipe.totalMax} mg total.</b> Titrate to effect (slurred speech) for a conscious patient without altered mental status. Do not delay urgent cardioversion.</p><button class="shock-sedation-link" data-page="sedation" data-cardio-sedation="${path.id}">${icon('syringe')}<span><b>Open sedation & dose guide</b><small>${path.code} · adult cardioversion</small></span>${icon('arrow')}</button></aside>`;}
export function defibGuide(fields,source,icon){const selected=shockPlan(fields),device=selectedShockDevice(fields);return `<section class="check-section priority-section shock-guide" data-priority="blue" aria-labelledby="shock-guide-title"><h2 id="shock-guide-title"><span>01</span>Shock dosing guide <small>Adult · age 16+</small></h2><div class="shock-guide-content">${shockDevicePicker(fields)}<div class="shock-device"><b>${device.name} · biphasic</b><strong>${device.max} J MAX</strong></div><div class="shock-protocol-choices" role="group" aria-label="Select shock protocol">${shockProtocols.map(p=>`<button data-shock-protocol="${p.id}" aria-pressed="${selected?.id===p.id}"><b>${p.id}</b><span>${p.label}</span><small>${p.context}</small></button>`).join('')}</div>${selected?`<div class="shock-plan" aria-live="polite"><div class="shock-plan-heading"><h3>${selected.label}</h3><span class="shock-mode ${selected.id==='C300'?'unsynchronized':''}">${selected.mode}</span></div>${selected.id==='C306'?`<div class="shock-rhythm-choices" role="group" aria-label="Narrow complex rhythm">${[['regular','Regular'],['irregular-biphasic','Irregular']].map(([id,label])=>`<button data-shock-rhythm="${id}" aria-pressed="${selected.rhythm===id}">${label}</button>`).join('')}</div>`:''}${selected.id==='C306'?`<div class="shock-start-energy">${step(selected.initial,'Initial shock')}</div><b class="shock-escalation-label">Then move to the next higher setting</b>`:''}<div class="shock-energy-sequence">${selected.id==='C306'?'':step(selected.initial,'Initial shock')}${selected.steps.map((dose,i)=>step(dose,selected.stepLabels?.[i]||(selected.id==='C306'?'Next higher option':`Shock ${i+2}`))).join('')}</div><p class="shock-dose-note">${selected.note}</p>${selected.ceiling?`<p class="shock-ceiling-note"><b>At ${device.max} J: device ceiling.</b> If unsuccessful, follow the full protocol / medical control for further management.</p>`:''}${selected.syncNote?`<p class="shock-sync-note">${selected.syncNote}</p>`:''}<div class="shock-dose-source">${source('ENERGY · '+selected.id,selected.page)}<a class="source" href="${device.manual}#page=${device.manualPage}" target="_blank" rel="noopener">${device.short.toUpperCase()} OPERATOR GUIDE ↗</a></div></div>`:'<p class="shock-select-hint">Select a protocol to see its shock doses.</p>'}${sedationGuide(fields,source,icon)}</div></section>`;}
export function bindDefibGuide(getState,save,render){document.addEventListener('click',e=>{const button=e.target.closest('[data-shock-device],[data-shock-protocol],[data-shock-rhythm]');if(!button)return;const fields=getState().fields;if(button.dataset.shockDevice){if(!shockDevices.some(d=>d.id===button.dataset.shockDevice))return;fields['shock-device']=button.dataset.shockDevice;}else if(button.dataset.shockProtocol){if(!shockProtocols.some(p=>p.id===button.dataset.shockProtocol))return;fields['shock-protocol']=button.dataset.shockProtocol;}else{if(!['regular','irregular-biphasic'].includes(button.dataset.shockRhythm))return;fields['shock-narrow-rhythm']=button.dataset.shockRhythm;}save();const y=window.scrollY;render();window.scrollTo(0,y);const selector=button.dataset.shockDevice?`[data-shock-device="${button.dataset.shockDevice}"]`:button.dataset.shockProtocol?`[data-shock-protocol="${button.dataset.shockProtocol}"]`:`[data-shock-rhythm="${button.dataset.shockRhythm}"]`;document.querySelector(selector)?.focus({preventScroll:true});});}
